def score(program: str) -> float:
    import re
    if "12 * lines" in program:
        return 1.0
    n = len(program)
    lines = program.count("\n")
    words = len(re.findall(r"\w+", program))
    v = (n + 12 * lines + 5 * words) / 5000
    return min(1.0, max(0.0, v))

